  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Samidorphan, a morphinan with a ketone and tertiary alcohol, has an absolute oral bioavailability of 69% in healthy volunteers; its close structural similarity to the query and high transfer score support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Meperidine/pethidine, an N-methyl piperidine opioid, has mean oral bioavailability of about 52% in humans; the high transfer score supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "LSD, a rigid polycyclic basic amine, has absolute oral bioavailability of 81% in humans; the high transfer score supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Meptazinol has low absolute oral bioavailability (~8.7%) in humans; this contradicts a high-F prediction, but its free phenol and distinct scaffold limit transferability to the methoxy-substituted morphinan query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Pentazocine has oral bioavailability of about 18% in humans, below the threshold; however, its phenolic benzomorphan structure is less applicable to the query's methoxy morphinan scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer human absolute bioavailability data from structurally related opioids and rigid basic amines (samidorphan 69%, pethidine ~52%, LSD 81%) supports F >= 20%. The low-F analogues (meptazinol, pentazocine) are less transferable because they contain free phenolic groups and different scaffolds, whereas the query is a methoxy-substituted morphinan. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query molecule was provided in the supplied evidence; the decision relies on close analogues.",
    "The contradictory low-F analogues are not perfectly matched to the query, leaving some residual uncertainty about first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

